export function splitKey(key: string): string[] {
  const parts: string[] = [];
  let current = '';
  let inQuotes = false;
  let quoteChar = '';
  let inBrackets = false;

  for (let i = 0; i < key.length; i++) {
    const char = key[i];

    if (char === '\\' && inQuotes && i + 1 < key.length) {
      current += key[++i];
    } else if ((char === '"' || char === "'") && (!inQuotes || char === quoteChar)) {
      inQuotes = !inQuotes;
      quoteChar = inQuotes ? char : '';
    } else if (char === '[' && !inQuotes) {
      if (inBrackets) {
        throw new ConfigError(`Unexpected '[' in key: ${key}`);
      }
      if (current.length > 0) {
        parts.push(current);
        current = '';
      }
      inBrackets = true;
    } else if (char === ']' && !inQuotes) {
      if (!inBrackets) {
        throw new ConfigError(`Unexpected ']' in key: ${key}`);
      }
      if (current.length > 0) {
        parts.push(current);
        current = '';
      }
      inBrackets = false;
    } else if (char === '.' && !inQuotes && !inBrackets) {
      if (current.length > 0) {
        parts.push(current);
        current = '';
      }
    } else {
      current += char;
    }
  }

  if (inQuotes) {
    throw new ConfigError(`Unclosed quote in key: ${key}`);
  }
  if (inBrackets) {
    throw new ConfigError(`Unclosed bracket in key: ${key}`);
  }

  if (current.length > 0 || parts.length === 0) {
    parts.push(current);
  }

  return parts;
}

export function parseConfig(raw: Record<string, any>): Record<string, any> {
  const result: Record<string, any> = {};

  for (const [key, value] of Object.entries(raw)) {
    const parts = splitKey(key);
    let current: any = result;

    for (let i = 0; i < parts.length - 1; i++) {
      const part = parts[i];
      const nextPart = parts[i + 1];
      const nextIsIndex = /^\d+$/.test(nextPart);

      if (!Object.hasOwn(current, part)) {
        current[part] = nextIsIndex ? [] : {};
      }
      current = current[part];
    }

    const lastPart = parts[parts.length - 1];
    current[lastPart] = value;
  }

  return result;
}

