export class ConfigError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'ConfigError';
  }
}

export function splitKey(key: string): string[] {
  const parts: string[] = [];
  let current = '';
  let inQuotes = false;
  let quoteChar = '';
  let inBrackets = false;

  for (let i = 0; i < key.length; i++) {
    const char = key[i];

    if (char === '\\' && inQuotes && i + 1 < key.length) {
      current += key[++i];
    } else if ((char === '"' || char === "'") && (!inQuotes || char === quoteChar)) {
      inQuotes = !inQuotes;
      quoteChar = inQuotes ? char : '';
    } else if (char === '[' && !inQuotes) {
      if (inBrackets) {
        throw new ConfigError(`Unexpected '[' in key: ${key}`);
      }
      if (current.length > 0) {
        parts.push(current);
        current = '';
      }
      inBrackets = true;
    } else if (char === ']' && !inQuotes) {
      if (!inBrackets) {
        throw new ConfigError(`Unexpected ']' in key: ${key}`);
      }
      if (current.length > 0) {
        parts.push(current);
        current = '';
      }
      inBrackets = false;
    } else if (char === '.' && !inQuotes && !inBrackets) {
      if (current.length > 0) {
        parts.push(current);
        current = '';
      }
    } else {
      current += char;
    }
  }

  if (inQuotes) {
